    @{ Name = 'A3L'; Width = 297000; Height = 630000; Standard = $false },
    @{ Name = 'A2L'; Width = 420000; Height = 804000; Standard = $false },
    @{ Name = 'A1L'; Width = 594000; Height = 1051000; Standard = $false },
    @{ Name = 'A0L'; Width = 841000; Height = 1399000; Standard = $false }
