$OpdsSource = @'
using System;
using System.Runtime.InteropServices;

namespace OpdsPrint
{
    public static class Spooler
    {
        [StructLayout(LayoutKind.Sequential)]
        private struct FormInfo1
        {
            public uint Flags;
            public IntPtr Name;
            public int Width;
            public int Height;
            public int Left;
            public int Top;
            public int Right;
            public int Bottom;
